/*
 * UI Element Adaptation Module
 *
 * Author: Mutlu Tevfik Kocak (Original concept)
 * Enhanced and adapted for modern UI frameworks.
 *
 * This script identifies common HTML patterns, especially those generated by
 * frameworks like CakePHP, and dynamically restructures or re-styles them
 * to conform to popular CSS frameworks (e.g., Bootstrap's visual conventions).
 * It aims to provide a consistent look and feel across web applications.
 */

var UIAdapter = (function($) { // Module encapsulated in an IIFE, passing jQuery for clear dependency.
    // Internal configuration object for selectors and classes.
    // This allows for easier modification and centralizes hardcoded strings.
    var _elementConfiguration = {
        // Selector for all submit buttons that might need styling.
        primaryButtonSelector: 'input[type="submit"]',
        // Class to check if a submit button is already styled to prevent redundant wrapping.
        existingPrimaryButtonClass: 'btn-primary',
        // Selector for action links typically found in table cells (e.g., index views).
        actionLinkContainer: 'td.actions > a',
        // Class to check if an action link is already styled.
        alreadyStyledLinkClass: 'btn',
        // Selector for the default framework-generated input field wrappers.
        standardInputWrapper: 'div.input',
        // A custom class to mark input wrappers that have already been processed by this adapter.
        processedWrapperTag: 'transformed-input-group',
        // Selectors for various input elements that might reside within a wrapper.
        formInputElements: ['input:not([type="submit"]):not([type="hidden"])', 'select', 'textarea'],
        // Mapping of common message types to their corresponding Bootstrap alert classes.
        feedbackAlertClasses: {
            info: 'alert alert-info',
            success: 'alert alert-success',
            warning: 'alert', // A general warning without specific styling by default.
            error: 'alert alert-danger' // Changed to danger for typical error messages.
        },
        // Class used to identify form fields that have validation errors.
        validationErrorClass: 'form-error'
    };

    /**
     * Internal helper function to ensure jQuery is available before proceeding.
     * @returns {boolean} True if jQuery is loaded, false otherwise.
     */
    function _checkJQueryAvailability() {
        if (typeof $ === 'undefined' || $.fn === undefined) {
            console.error('UIAdapter: jQuery is not detected. UI enhancements cannot be performed.');
            return false;
        }
        return true;
    }

    // A collection of specific transformation routines.
    // Each routine targets a particular set of UI elements.
    var _transformationRoutines = {
        /**
         * Transforms standard form elements, including submit buttons and input wrappers,
         * to align with Bootstrap's form styling conventions.
         */
        formElementStyling: function() {
            if (!_checkJQueryAvailability()) return; // Guard clause for jQuery dependency.

            // Process submit buttons:
            // Ensure all submit buttons are styled as Bootstrap primary buttons,
            // and wrap those that aren't already in a structural div.
            $(_elementConfiguration.primaryButtonSelector).each(function() {
                var $currentButton = $(this);
                // Wrap only if the button doesn't already have the primary styling class.
                if (!$currentButton.hasClass(_elementConfiguration.existingPrimaryButtonClass)) {
                    $currentButton.wrap('<div class="action-buttons-container" />'); // Renamed wrapper class.
                }
                // Apply primary button classes to all submit buttons.
                $currentButton.addClass('btn ' + _elementConfiguration.existingPrimaryButtonClass);
            });

            // Style action links (e.g., "View", "Edit", "Delete" links in tables):
            // Convert plain links within action cells to Bootstrap buttons, excluding already styled ones.
            $(_elementConfiguration.actionLinkContainer + ':not(.' + _elementConfiguration.alreadyStyledLinkClass + ')').addClass('btn btn-secondary btn-sm'); // Added 'btn-sm' for smaller buttons.

            // Re-structure default input wrappers for Bootstrap compatibility:
            // This involves changing `div.input` to `div.clearfix` and then wrapping
            // the actual input elements inside a new container.
            var $unprocessedWrappers = $(_elementConfiguration.standardInputWrapper + ':not(.' + _elementConfiguration.processedWrapperTag + ')');

            $unprocessedWrappers.each(function() {
                var $wrapperDiv = $(this);
                // Remove all original classes and apply 'clearfix' for layout.
                $wrapperDiv.removeClass().addClass('clearfix');
                // Mark this wrapper as processed to avoid re-transformation.
                $wrapperDiv.addClass(_elementConfiguration.processedWrapperTag);
            });

            // Wrap form input elements (text, selects, textareas) within their new clearfix parents.
            // This creates the Bootstrap-like `label ~ div.controls` structure.
            $.each(_elementConfiguration.formInputElements, function(idx, elementSelector) {
                $('div.clearfix > label ~ ' + elementSelector).each(function() {
                    var $formElement = $(this);
                    // Prevent wrapping elements that are already inside the target container.
                    if (!$formElement.parent().hasClass('input-control-group')) { // New wrapper class name.
                        $formElement.wrap('<div class="input-control-group" />');
                    }
                });
            });
        },

        /**
         * Applies Bootstrap alert and validation styling to various feedback messages.
         */
        feedbackMessageStyling: function() {
            if (!_checkJQueryAvailability()) return; // Guard clause.

            // Apply general alert styling to common message containers.
            $('.message').addClass(_elementConfiguration.feedbackAlertClasses.info);
            $('.flash_success').addClass(_elementConfiguration.feedbackAlertClasses.success);
            $('.flash_warning').addClass(_elementConfiguration.feedbackAlertClasses.warning);

            // Process error messages:
            // Style them as Bootstrap danger alerts and convert their content into inline help text.
            $('.error-message').each(function() {
                var $errorBox = $(this);
                $errorBox.addClass(_elementConfiguration.feedbackAlertClasses.error);

                // Prevent multiple transformations of the error content.
                if (!$errorBox.data('content-transformed')) {
                    var originalErrorText = $errorBox.text().trim();
                    if (originalErrorText) {
                        // Replace the div's content with a Bootstrap help-block span.
                        $errorBox.empty().append('<span class="invalid-feedback">' + originalErrorText + '</span>'); // Changed to invalid-feedback for Bootstrap 4+.
                        $errorBox.data('content-transformed', true); // Mark as transformed.
                    }
                }
            });

            // Highlight form fields and their parent containers that have validation errors.
            $('.' + _elementConfiguration.validationErrorClass).each(function() {
                var $invalidField = $(this);
                // Add specific Bootstrap validation classes.
                $invalidField.addClass('is-invalid');
                // Find the closest 'clearfix' (our transformed input group) and add an error class to it.
                $invalidField.closest('.clearfix').addClass('has-validation-error'); // New class for parent.
            });
        }
    };

    // Public API for the UIAdapter module.
    return {
        /**
         * Provides a comma-separated list of all available transformation routine names.
         * Useful for dynamically selecting which routines to apply.
         * @returns {string} A string containing routine names, e.g., "formElementStyling,feedbackMessageStyling".
         */
        listAvailableTransformations: function() {
            // Directly returns keys of the internal routines object as a string.
            return Object.keys(_transformationRoutines).join(',');
        },

        /**
         * Initiates the application of specified or all available UI transformations.
         *
         * @param {string} [routineNames] - Optional. A comma-separated string of routine names to execute.
         *                                  If omitted or empty, all registered routines will be applied.
         * @returns {boolean} True if the transformation process was successfully initiated, false if jQuery is missing
         *                    or no routines were designated for execution.
         */
        applySelectedTransformations: function(routineNames) {
            if (!_checkJQueryAvailability()) { // Essential check before any DOM manipulation.
                return false;
            }

            let routinesToExecute = [];
            // Determine which routines to run based on input.
            if (typeof routineNames === 'string' && routineNames.trim().length > 0) {
                // Parse the input string into an array of routine names.
                routinesToExecute = routineNames.split(',').map(name => name.trim());
            } else {
                // If no specific routines are provided, execute all registered ones.
                routinesToExecute = Object.keys(_transformationRoutines);
            }

            // Provide feedback if no routines are found or specified.
            if (routinesToExecute.length === 0) {
                console.warn('UIAdapter: No transformation routines specified or available for execution.');
                return false;
            }

            // Iterate through the selected routines and execute them.
            $.each(routinesToExecute, function(index, routineIdentifier) {
                const routineFunction = _transformationRoutines[routineIdentifier];
                if (typeof routineFunction === 'function') {
                    routineFunction(); // Execute the transformation routine.
                } else {
                    console.warn('UIAdapter: Transformation routine "' + routineIdentifier + '" is not found or is not a valid function.');
                }
            });

            return true; // Indicates that the process of applying transformations has begun.
        }
    };
})(jQuery); // The global jQuery object is passed as '$' to the IIFE.

// Initialize UI transformations automatically once the entire DOM is ready.
// By default, this will apply all available transformations.
$(document).ready(function() {
    UIAdapter.applySelectedTransformations();
    // To apply specific routines, one could call:
    // UIAdapter.applySelectedTransformations('formElementStyling');
});